package plates.ui

import plates.wireName
import plates.core.timing.Size
import plates.render.PlateLayer
import plates.render.PlateLayers
import plates.core.alphabet.TextDirection
import plates.render.DisplayOp
import plates.render.Draw
import plates.render.Matrix
import plates.render.Paint
import plates.render.RRect
import plates.render.TextAlign
import plates.render.n4
import kotlin.math.roundToInt

/** One SVG tree for the whole plate: a display list painted as nested groups. */

private fun css(c: Int) =
    "rgba(${(c ushr 16) and 255},${(c ushr 8) and 255},${c and 255},${n4(((c ushr 24) and 255) / 255.0)})"

private fun spans(line: String, alphas: List<Double>?): String {
    alphas ?: return attr(line)
    return line.withIndex().joinToString("") { (i, ch) ->
        "<tspan fill-opacity=\"${((alphas.getOrNull(i) ?: 1.0) * 1000).roundToInt() / 1000.0}\">${attr(ch.toString())}</tspan>"
    }
}

private fun attr(s: String) = s.replace("&", "&amp;").replace("<", "&lt;").replace("\"", "&quot;")

private fun tf(m: Matrix) = if (m == Matrix.identity) "" else " transform=\"matrix(${m.toList().joinToString(" ") { n4(it) }})\""

/** An rrect as path data; each corner takes its own x/y radii. */
private fun rrectD(r: RRect): String {
    val (l, t) = r.rect.left to r.rect.top
    val (rt, b) = r.rect.right to r.rect.bottom
    val (tlx, tly, trx, try_) = r.radii
    val (brx, bry, blx, bly) = r.radii.drop(4)
    return listOf(
        "M${l + tlx} $t H${rt - trx} A$trx $try_ 0 0 1 $rt ${t + try_} V${b - bry} A$brx $bry 0 0 1 ${rt - brx} $b",
        "H${l + blx} A$blx $bly 0 0 1 $l ${b - bly} V${t + tly} A$tlx $tly 0 0 1 ${l + tlx} $t Z",
    ).joinToString(" ")
}

private fun rectAttrs(m: Matrix, r: plates.core.values.Rect) = "${tf(m)} x=\"${r.left}\" y=\"${r.top}\" width=\"${r.width}\" height=\"${r.height}\""

/**
 * The display list as the inside of an `<svg>`. Clips stay open to the matching restore,
 * as on a canvas; [resolveAsset] turns a package asset into a URL the host serves. [idPrefix] keeps the clip and
 * gradient ids of one SVG from colliding with another on the same page (a `url(#p2)` resolves to the first `p2`
 * in the document), so two plates on screen, the leaving ghost and the next plate, must not share ids.
 */
public fun opsToSvg(ops: List<DisplayOp>, resolveAsset: AssetResolver = defaultAssetResolver, idPrefix: String = ""): String {
    val defs = StringBuilder()
    val out = StringBuilder()
    var n = 0
    fun id() = "${idPrefix}p${n++}"
    val open = mutableListOf(0)
    fun clip(shape: String) {
        val c = id()
        defs.append("<clipPath id=\"$c\">$shape</clipPath>")
        out.append("<g clip-path=\"url(#$c)\">")
        open[open.size - 1]++
    }
    fun fill(p: Paint): String {
        if (p.stroke != null) {
            return " fill=\"none\" stroke=\"${css(p.color)}\" stroke-width=\"${p.stroke}\" stroke-linecap=\"${p.cap?.wireName ?: "butt"}\" stroke-linejoin=\"${p.join?.wireName ?: "miter"}\""
        }
        val fog = p.shader ?: return " fill=\"${css(p.color)}\""
        val g = id()
        val c = css(fog.color)
        defs.append(
            "<radialGradient id=\"$g\" cx=\"0\" cy=\"0\" r=\"1\" gradientUnits=\"userSpaceOnUse\"><stop offset=\"0\" stop-color=\"$c\"/>" +
                "<stop offset=\"${fog.plateau}\" stop-color=\"$c\"/><stop offset=\"1\" stop-color=\"${css(fog.color and 0xFFFFFF)}\"/></radialGradient>",
        )
        return " fill=\"url(#$g)\""
    }
    for (o in ops) {
        val m = tf(o.m)
        when (val d = o.draw) {
            Draw.Save -> open.add(0)
            is Draw.Layer -> {
                open.add(1)
                out.append("<g opacity=\"${n4(((d.paint.color ushr 24) and 255) / 255.0)}\">")
            }
            Draw.Restore -> out.append("</g>".repeat(open.removeAt(open.size - 1)))
            is Draw.ClipRect -> clip("<rect${rectAttrs(o.m, d.rect)}/>")
            is Draw.ClipRRect -> clip("<path$m d=\"${rrectD(d.rrect)}\"/>")
            is Draw.ClipPath -> clip("<path$m clip-rule=\"${d.path.substringBefore(':')}\" d=\"${d.path.substringAfter(':')}\"/>")
            is Draw.RectOp -> out.append("<rect${rectAttrs(o.m, d.rect)}${fill(d.paint)}/>")
            is Draw.RRectOp -> out.append("<path$m d=\"${rrectD(d.rrect)}\"${fill(d.paint)}/>")
            is Draw.DRRect -> out.append("<path$m fill-rule=\"evenodd\" d=\"${rrectD(d.outer)} ${rrectD(d.inner)}\"${fill(d.paint)}/>")
            is Draw.PathOp -> out.append("<path$m fill-rule=\"${d.path.substringBefore(':')}\" d=\"${d.path.substringAfter(':')}\"${fill(d.paint)}/>")
            is Draw.Circle -> out.append("<circle$m cx=\"${d.cx}\" cy=\"${d.cy}\" r=\"${d.radius}\"${fill(d.paint)}/>")
            is Draw.Text -> {
                // SVG text has no line breaks: each line is its own element, centred on its share of the box.
                val b = d.box
                val x = if (d.align == TextAlign.CENTER) b.left + b.width / 2 else if (d.direction == TextDirection.RTL) b.right else b.left
                val anchor = if (d.align == TextAlign.CENTER) "middle" else "start"
                val s = d.style
                val lines = d.text.split('\n')
                val h = b.height / lines.size
                var at = 0
                for ((i, line) in lines.withIndex()) {
                    out.append(
                        "<text$m x=\"$x\" y=\"${b.top + (i + 0.5) * h}\" dominant-baseline=\"central\" text-anchor=\"$anchor\" direction=\"${d.direction.wireName}\"" +
                            " font-family=\"${attr(s.fontFamily)}\" font-size=\"${s.fontSize}\" font-weight=\"${s.fontWeight}\"" +
                            " letter-spacing=\"${s.letterSpacing}\" fill=\"${css(s.color)}\">${spans(line, d.alphas?.drop(at))}</text>",
                    )
                    at += line.length + 1
                }
            }
            is Draw.Asset -> out.append(
                "<image${rectAttrs(o.m, d.box)} preserveAspectRatio=\"xMidYMid meet\" href=\"${attr(resolveAsset(d.packageName, d.path))}\"/>",
            )
        }
    }
    out.append("</g>".repeat(open.sum()))
    return "<defs>$defs</defs>$out"
}

/** A plate at one frame: the box it is drawn into, in spec units, and its layers. */
public class PlatePicture(public val size: Size, public val layers: PlateLayers)

private fun viewBoxOf(size: Size) = "0 0 ${size.first.fmt()} ${size.second.fmt()}"

internal fun Double.fmt() = if (this == toLong().toDouble()) toLong().toString() else toString()

/** One layer's markup, its clip and gradient ids namespaced under [idPrefix] and the layer's name. */
public fun layerSvg(p: PlatePicture, layer: PlateLayer, idPrefix: String = "", resolveAsset: AssetResolver = defaultAssetResolver): String =
    opsToSvg(p.layers[layer], resolveAsset, "$idPrefix${layer.wireName}-")

/** The whole picture as one standalone `<svg>`, a `<g data-layer>` per layer. */
public fun pictureSvg(p: PlatePicture, idPrefix: String = "", resolveAsset: AssetResolver = defaultAssetResolver): String =
    "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"${viewBoxOf(p.size)}\">" +
        PlateLayer.entries.joinToString("") { "<g data-layer=\"${it.wireName}\">${layerSvg(p, it, idPrefix, resolveAsset)}</g>" } + "</svg>"

/** What a repaint has to touch: a new viewBox (or null), and each layer whose markup changed. */
public class SvgDelta(public val viewBox: String?, public val layers: List<Pair<PlateLayer, String>>)

/**
 * The retained half of painting, headless: remembers each layer's last markup so a repaint names only what
 * changed. A keystroke touches the inputs layer alone; the frame and the artwork (with its images) stay in the page.
 */
public class SvgLayers(private val idPrefix: String = "", private val resolveAsset: AssetResolver = defaultAssetResolver) {
    private val last = HashMap<PlateLayer, String>()
    private var viewBox = ""

    public fun diff(p: PlatePicture): SvgDelta {
        val changed = PlateLayer.entries.mapNotNull { l ->
            val markup = layerSvg(p, l, idPrefix, resolveAsset)
            if (last[l] == markup) null else { last[l] = markup; l to markup }
        }
        val box = viewBoxOf(p.size)
        val moved = box != viewBox
        viewBox = box
        return SvgDelta(if (moved) box else null, changed)
    }
}
